def parse_effective_args(text: str) -> dict | None:
    """Parse the args Namespace that the authors' train_FEGNN.py prints after
    set_best_train_args() has applied the FEGNN_params.csv row - i.e. the REAL
    effective configuration of the run (not a reconstruction)."""
    m = re.search(r"Namespace\((.*)\)", text, re.S)
    if not m:
        return None
    import ast

    out: dict = {}
    for part in re.split(r",(?=\s*[A-Za-z_]\w*=)", m.group(1)):
        if "=" not in part:
            continue
        k, v = part.split("=", 1)
        try:
            out[k.strip()] = ast.literal_eval(v.strip())
        except Exception:
            out[k.strip()] = v.strip()
    return out


